<script setup>
import{ref,onMounted,onBeforeUnmount}from'vue';import axios from'axios';import{Head,Link}from'@inertiajs/vue3';import AuthenticatedLayout from'@/Layouts/AuthenticatedLayout.vue';
defineProps({clients:Array});const form=ref({client_id:'',source:'list',operation_id:'',page:1,per_page:20,consent:false});
const result=ref(null),rows=ref([]),error=ref(''),busy=ref(false);
const date=v=>new Date(v).toLocaleString('es-MX');
async function load(){const r=await axios.get(route('financial.receipts.consent.records'));rows.value=r.data.data;}
async function issue(){busy.value=true;error.value='';result.value=null;try{const r=await axios.post(route('financial.receipts.consent.issue'),form.value);result.value=r.data.data;form.value.consent=false;await load();}catch(e){error.value=Object.values(e.response?.data?.errors||{}).flat().join(' ')||e.response?.data?.message||'No se pudo autorizar la consulta.';}finally{busy.value=false;}}
async function revoke(row){busy.value=true;error.value='';try{await axios.post(route('financial.receipts.consent.revoke',{grantId:row.id}));if(result.value?.id===row.id)result.value=null;await load();}catch(e){error.value=e.response?.data?.message||'No se pudo revocar.';}finally{busy.value=false;}}
onMounted(()=>load().catch(()=>error.value='No se pudo cargar el historial.'));onBeforeUnmount(()=>result.value=null);
</script><template><Head title="Autorizar consulta API"/><AuthenticatedLayout><template #header><h2 class="text-2xl font-bold text-[#00338D]">Autorizar consulta de comprobantes por API</h2></template>
<div class="bg-[#F5F8FC] min-h-screen p-6"><div class="max-w-5xl mx-auto"><Link :href="route('financial.receipts.index')">Volver a mis comprobantes</Link>
<p class="mt-4">Permite a la aplicación elegida consultar tus comprobantes mediante una petición concreta. No permite mover dinero ni consultar wallets ajenas.</p>
<form @submit.prevent="issue" class="bg-white border rounded-xl p-5 mt-5 space-y-4">
<label class="block">Aplicación<select v-model="form.client_id" required class="block w-full border rounded p-2"><option value="">Selecciona una aplicación registrada</option><option v-for="client in clients" :key="client.id" :value="client.id">{{client.name}} · {{client.id}}</option></select></label><p v-if="!clients.length">No hay aplicaciones activas con permiso de consulta de comprobantes.</p>
<label class="block">Consulta<select v-model="form.source" @change="form.operation_id=''" class="block w-full border rounded p-2"><option value="list">Una página de mi listado</option><option value="transaction">Una transacción propia</option><option value="purchase">Un pago de compra propio</option></select></label>
<label v-if="form.source!=='list'" class="block">ID de operación<input v-model="form.operation_id" required maxlength="36" class="block w-full border rounded p-2"/></label>
<div v-else class="grid grid-cols-2 gap-3"><label>Página<input v-model.number="form.page" type="number" min="1" max="1000000" required class="block border rounded p-2 w-full"/></label><label>Registros por página<input v-model.number="form.per_page" type="number" min="1" max="50" required class="block border rounded p-2 w-full"/></label></div>
<label class="flex gap-3"><input v-model="form.consent" type="checkbox" required/>Autorizo expresamente a esta aplicación a realizar esta consulta sobre mis comprobantes.</label>
<button :disabled="busy||!clients.length" class="bg-blue-800 text-white px-4 py-2 rounded">Autorizar consulta</button><p v-if="error" role="alert" class="text-red-700">{{error}}</p></form>
<section v-if="result" class="bg-white border rounded-xl p-5 mt-5"><h3 class="font-bold">Autorización creada</h3><p>Vence: {{date(result.expires_at)}}</p><p>La prueba se muestra una sola vez y desaparece al salir de esta pantalla. Entrégala únicamente a la aplicación elegida.</p><label class="block mt-3">X-User-Authorization<textarea :value="result.proof" readonly class="block w-full border rounded p-2 font-mono"/></label><p class="mt-3 font-mono break-all">{{result.method}} {{result.request_path}}</p><p class="text-sm">El token de servicio y esta prueba deben pertenecer al cliente {{result.client_id}}. Cambiar la consulta requiere una nueva autorización.</p></section>
<section class="bg-white border rounded-xl p-5 mt-5"><h3 class="font-bold">Mis autorizaciones recientes</h3><p v-if="!rows.length">No hay autorizaciones.</p><article v-for="row in rows" :key="row.id" class="border-t mt-3 pt-3"><p>{{row.client_name}} · {{row.revoked?'Revocada':row.expired?'Vencida':'Vigente'}}</p><p class="font-mono text-sm break-all">{{row.request_path}}</p><p>Vence: {{date(row.expires_at)}}</p><button v-if="!row.revoked&&!row.expired" :disabled="busy" @click="revoke(row)" class="text-red-700 mt-2">Revocar autorización</button></article></section>
</div></div></AuthenticatedLayout></template>
